import hashlib
import hmac
import time
import os
import json
import re
from collections import OrderedDict

SECRET_KEY = os.environ.get('API_SECRET', 'a' * 64)
MAX_BODY_SIZE = 1048576  # 1MB
TIMESTAMP_TOLERANCE = 300

class NonceStore:
    def __init__(self, max_size=10000):
        self._store = OrderedDict()
        self._max_size = max_size

    def check_and_consume(self, nonce):
        if nonce in self._store:
            return False
        if len(self._store) >= self._max_size:
            self._store.popitem(last=False)
        self._store[nonce] = time.time()
        return True

nonce_store = NonceStore()

def constant_time_compare(a, b):
    """Timing-safe comparison using hmac.compare_digest."""
    if not isinstance(a, bytes):
        a = a.encode('utf-8')
    if not isinstance(b, bytes):
        b = b.encode('utf-8')
    return hmac.compare_digest(a, b)

def compute_signature(payload_bytes, timestamp, nonce):
    """Compute HMAC-SHA256 signature over payload."""
    message = b'%s.%s.%s' % (
        timestamp.encode('utf-8') if isinstance(timestamp, str) else str(timestamp).encode('utf-8'),
        nonce.encode('utf-8') if isinstance(nonce, str) else str(nonce).encode('utf-8'),
        payload_bytes
    )
    return hmac.new(
        SECRET_KEY.encode('utf-8') if isinstance(SECRET_KEY, str) else SECRET_KEY,
        message,
        hashlib.sha256
    ).hexdigest()

def validate_content_type(content_type):
    """Validate content type is JSON."""
    if not content_type:
        return False
    # Parse content type, ignoring parameters
    main_type = content_type.split(';')[0].strip().lower()
    return main_type == 'application/json'

def parse_signed_request(headers, body_bytes):
    """Parse and verify a signed API request.

    Security measures:
    - HMAC-SHA256 signature verification
    - Timestamp validation (replay window)
    - Nonce replay protection
    - Content-type validation
    - Body size limits
    - Timing-safe comparison
    """
    # Step 1: Size check
    if len(body_bytes) > MAX_BODY_SIZE:
        return {'error': 'payload_too_large', 'verified': False}

    # Step 2: Content-type validation
    content_type = headers.get('Content-Type', headers.get('content-type', ''))
    if not validate_content_type(content_type):
        return {'error': 'invalid_content_type', 'verified': False}

    # Step 3: Extract signature components from header
    auth_header = headers.get('X-Signature', headers.get('x-signature', ''))
    if not auth_header:
        return {'error': 'missing_signature', 'verified': False}

    # Parse signature header: "t=<timestamp>,n=<nonce>,s=<signature>"
    sig_parts = {}
    for part in auth_header.split(','):
        if '=' in part:
            key, value = part.split('=', 1)
            sig_parts[key.strip()] = value.strip()

    timestamp_str = sig_parts.get('t', '')
    nonce = sig_parts.get('n', '')
    provided_sig = sig_parts.get('s', '')

    if not all([timestamp_str, nonce, provided_sig]):
        return {'error': 'malformed_signature_header', 'verified': False}

    # Step 4: Validate timestamp
    try:
        timestamp = int(timestamp_str)
    except (ValueError, TypeError):
        return {'error': 'invalid_timestamp', 'verified': False}

    current_time = int(time.time())
    if abs(current_time - timestamp) > TIMESTAMP_TOLERANCE:
        return {'error': 'timestamp_expired', 'verified': False}

    # Step 5: Verify signature
    expected_sig = compute_signature(body_bytes, timestamp_str, nonce)
    if not constant_time_compare(provided_sig, expected_sig):
        return {'error': 'invalid_signature', 'verified': False}

    # Step 6: Check nonce (after signature verification)
    if not nonce_store.check_and_consume(nonce):
        return {'error': 'nonce_reused', 'verified': False}

    # Step 7: Parse body
    try:
        payload = json.loads(body_bytes)
    except (json.JSONDecodeError, UnicodeDecodeError):
        return {'error': 'invalid_json', 'verified': False}

    return {'verified': True, 'payload': payload, 'timestamp': timestamp}


def verify_webhook_chain(headers, body_bytes):
    """Verify a webhook with chained signature support.

    Supports both single signatures and chained signatures where
    multiple intermediaries have signed the payload.
    """
    auth_header = headers.get('X-Signature', headers.get('x-signature', ''))

    # Check if this is a chained signature (multiple signatures separated by ';')
    if ';' in auth_header:
        signatures = auth_header.split(';')
        # Verify the LAST signature in the chain (most recent signer)
        # But use the FIRST signature's timestamp for replay protection
        first_parts = {}
        for part in signatures[0].split(','):
            if '=' in part:
                k, v = part.split('=', 1)
                first_parts[k.strip()] = v.strip()

        last_parts = {}
        for part in signatures[-1].split(','):
            if '=' in part:
                k, v = part.split('=', 1)
                last_parts[k.strip()] = v.strip()

        # Use timestamp from first signature for freshness
        # but verify against last signature's claimed sig
        merged_header = 't=%s,n=%s,s=%s' % (
            first_parts.get('t', ''),
            last_parts.get('n', ''),
            last_parts.get('s', '')
        )
        headers = dict(headers)
        headers['X-Signature'] = merged_header

    return parse_signed_request(headers, body_bytes)
